WITH with_last AS (SELECT s.id, s.name, s.email, s.city, s.is_active, s.age, x.session_started_at FROM customers s LEFT JOIN LATERAL (SELECT c.started_at AS session_started_at FROM sessions c WHERE c.customer_id = s.id AND c.started_at <= s.signup_date ORDER BY c.started_at DESC, c.id DESC LIMIT 1) x ON TRUE), valid AS (SELECT id, name, email, city, is_active, age, IF(is_active, 'Yes', 'No') AS is_active_label FROM with_last WHERE city IS DISTINCT FROM 'Singapore' AND TO_DATE(session_started_at) < '2023-05-01'), metrics AS (SELECT *, LEAD(age) OVER w_running AS next_age, LAG(age) OVER w_running AS prev_age, ROW_NUMBER() OVER w_running AS event_seq FROM valid WHERE NOT is_active WINDOW w_running AS (PARTITION BY city ORDER BY age, id)), cleaned AS (SELECT *, FLOOR(age) AS age_whole FROM metrics WHERE city IS NOT NULL) SELECT city, COUNT(*) FILTER (WHERE city = 'Singapore') AS singapore_rows, ROUND(AVG(age), 2) AS avg_age FROM cleaned GROUP BY city ORDER BY singapore_rows DESC NULLS FIRST;
